#!/usr/bin/env node
const { Command } = require('commander');
const program = new Command();

program
  .name('{{bin_name}}')
  .description('{{bin_name}} CLI')
  .version('0.1.0')
  .option('--{{option_a}} <value>', '{{option_a}} input')
  .option('-v, --verbose', 'verbose output')
  .action((opts) => {
    if (opts.verbose) console.error('opts', opts);
    console.log(`{{bin_name}} got: ${opts.{{option_a}}}`);
  });

program.parse();
